// Build search payload for the current cliente
const cliente = $input.first().json;

const name = (cliente.nombre_comercial || '').trim();
const locality = (cliente.localidad || '').trim();
const provincia = (cliente.provincia || '').trim();
const address = (cliente.direccion || '').trim();

if (!name) {
  return [{ json: { skipped: true, reason: 'empty_name', cliente } }];
}

return [{ json: {
  cliente,
  searchPayload: { name, locality, provincia, address }
} }];

// Score search candidates against the cliente
const raw = $input.first().json;
const wrapperResponse = raw; // HTTP Request returns body as json
const cliente = raw.cliente;
const candidates = wrapperResponse.candidates || [];

function normalize(s) {
  if (!s) return '';
  return s.toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['']/g, "'")
    .trim();
}

function levenshtein(a, b) {
  if (!a || !b) return 0;
  const m = a.length, n = b.length;
  if (m === 0) return n === 0 ? 1 : 0;
  if (n === 0) return 0;
  const dp = Array.from({length: m+1}, () => new Array(n+1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i-1] === b[j-1] ? 0 : 1;
      dp[i][j] = Math.min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + cost);
    }
  }
  return 1 - (dp[m][n] / Math.max(m, n));
}

function scoreName(clientName, candidateName) {
  const nc = normalize(clientName);
  const cc = normalize(candidateName);
  if (!nc || !cc) return 0;
  if (nc === cc) return 1.0;
  if (cc.includes(nc) || nc.includes(cc)) return 0.85;
  return levenshtein(nc, cc);
}

function scoreMatch(cliente, candidate) {
  const nameScore = scoreName(cliente.nombre_comercial || '', candidate.name || '');

  const clienteLocality = normalize(cliente.localidad || '');
  const clienteProvincia = normalize(cliente.provincia || '');
  const candidateAddress = normalize(candidate.address || '');

  const localityMatch = clienteLocality && candidateAddress.includes(clienteLocality) ? 1 : 0;
  const provinciaMatch = clienteProvincia && candidateAddress.includes(clienteProvincia) ? 0.5 : 0;

  let phoneMatch = 0;
  const clientePhone = (cliente.telefono || '').replace(/\D/g, '');
  if (clientePhone && clientePhone.length >= 6) {
    if (candidate.address && candidate.address.includes(cliente.telefono)) {
      phoneMatch = 0.2;
    }
  }

  const rawScore = 0.55 * nameScore + 0.25 * (localityMatch || provinciaMatch) + 0.1 * phoneMatch;
  const finalScore = nameScore > 0.92 ? Math.min(1.0, rawScore + 0.1) : rawScore;

  return {
    score: Math.round(finalScore * 100) / 100,
    nameScore: Math.round(nameScore * 100) / 100,
    localityMatch,
    provinciaMatch,
    phoneMatch,
  };
}

const scored = candidates.map(c => ({...c, ...scoreMatch(cliente, c)}));
scored.sort((a, b) => b.score - a.score);

const best = scored[0];
const threshold = 0.65;

if (!best || best.score < threshold) {
  return [{ json: {
    cliente,
    matched: false,
    bestCandidate: best || null,
    candidatesScored: scored.slice(0, 3),
    threshold,
    message: 'No candidate above threshold',
  } }];
}

return [{ json: {
  cliente,
  matched: true,
  bestCandidate: best,
  candidatesScored: scored.slice(0, 3),
  threshold,
  message: 'Match found: ' + best.name + ' (score: ' + best.score + ')',
} }];
